const config     = $('Configuration').first().json;
const webhookRaw = $('Receive Gap Webhook').first().json;
const gap        = webhookRaw.body || webhookRaw;

const relatedRaw  = $('Fetch Related Gaps').first().json;
const related     = Array.isArray(relatedRaw) ? relatedRaw : [];
const relatedCount = Math.max(0, related.length - 1);

console.log('Generating insight for gap: ' + (gap.customer_question || gap.subject) + ' | theme: ' + gap.theme + ' | related: ' + relatedCount);

const sys = 'You are a marketing strategist for Boldr, a Singapore-based watch micro-brand known for honest materials, craftsmanship, and transparency.\n\nA customer just asked a question that the CS team could NOT answer — meaning this information does not exist on Boldr\'s product pages or in their knowledge base.\n\nThis is a signal: when customers ask something that is not answered, they are revealing a content gap that competitors are likely also ignoring. Your job is to assess whether this gap is a marketing opportunity Boldr could own.\n\nWatch brand context in SEA: Most watch brands in Southeast Asia do not publish detailed materials safety data, sustainability sourcing, or honest technical specs in their marketing. There is a clear opening for a brand that speaks openly about these things.\n\nScore each dimension 1–10:\n- score_uniqueness: how underserved is this angle among watch brands in SEA? (10 = nobody does this)\n- score_conversion: how likely does directly addressing this remove a real purchase barrier? (10 = very likely)\n- score_overall: holistic marketing potential\n\nRespond ONLY with valid JSON, no markdown, no extra text:\n{\n  "marketing_angle": "One sentence: the market position this gap reveals Boldr could own",\n  "campaign_idea": "Specific actionable content or campaign idea in 2–3 sentences",\n  "test_suggestion": "The cheapest fastest way to test this angle — one Instagram post, one FAQ update, or one email",\n  "score_uniqueness": 8,\n  "score_conversion": 7,\n  "score_overall": 8,\n  "rationale": "One sentence explaining why it scores as it does"\n}';

const usr = [
  'Customer question: ' + (gap.customer_question || gap.subject || 'Unknown'),
  'Theme: '             + (gap.theme             || 'knowledge_gap'),
  'Buyer persona: '     + (gap.buyer_persona      || 'unknown'),
  'Channel: '           + (gap.channel            || 'email'),
  'Gap reason: '        + (gap.gap_reason         || 'Not in knowledge base'),
  'Other customers with questions in the same theme: ' + relatedCount
].join('\n');

return [{ json: {
  gap, config, related_count: relatedCount,
  request_body: {
    model:      config.QWEN_MODEL,
    max_tokens: 600,
    messages:   [{ role: 'system', content: sys }, { role: 'user', content: usr }]
  }
} }];

const response = $input.first();
const orig     = $('Build Qwen Insight Request').first().json;
const rawText  = response.json.choices?.[0]?.message?.content || '';
const cleaned  = rawText.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();
let r;
try { r = JSON.parse(cleaned); } catch(e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) { try { r = JSON.parse(m[0]); } catch(e2) { r = null; } }
}
if (!r) {
  r = { marketing_angle: 'Insight parse error', campaign_idea: '', test_suggestion: '',
        score_uniqueness: 5, score_conversion: 5, score_overall: 5, rationale: 'Parse failed: ' + rawText.substring(0,100) };
}
console.log('Insight ready — overall score: ' + r.score_overall + ' | angle: ' + r.marketing_angle);
const gap = orig.gap;
return [{ json: {
  ticket_id:         gap.ticket_id         || '',
  theme:             gap.theme             || 'knowledge_gap',
  buyer_persona:     gap.buyer_persona      || 'unknown',
  channel:           gap.channel            || 'email',
  customer_question: gap.customer_question  || gap.subject || '',
  marketing_angle:   r.marketing_angle      || '',
  campaign_idea:     r.campaign_idea        || '',
  test_suggestion:   r.test_suggestion      || '',
  score_uniqueness:  r.score_uniqueness      || 5,
  score_conversion:  r.score_conversion      || 5,
  score_overall:     r.score_overall         || 5,
  rationale:         r.rationale             || '',
  config:            orig.config
} }];
